<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="csrf-token" content="{{ csrf_token() }}">
<title>JEE / NEET CBT · Tagore ERP</title>
<link rel="stylesheet" href="{{ asset('tagore-erp.css') }}">
<style>
body{margin:0;background:#f3f6fb;color:#172033;font:15px system-ui}.shell{max-width:1100px;margin:auto;padding:22px 16px}.panel{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:18px;margin:12px 0}.muted{color:#64748b}.grid{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:14px}.btn{border:0;border-radius:8px;padding:10px 15px;background:#173b69;color:white;cursor:pointer}.btn.secondary{background:#e8eef6;color:#173b69}.btn:disabled{opacity:.5;cursor:not-allowed}.exam{display:flex;justify-content:space-between;align-items:center;gap:12px}.question{font-size:18px;line-height:1.55;white-space:pre-wrap}.choice{display:flex;gap:10px;padding:12px;border:1px solid #dbe3ee;border-radius:9px;margin:9px 0;cursor:pointer}.choice input{margin-top:4px}.palette{display:grid;grid-template-columns:repeat(5,1fr);gap:7px}.palette button{padding:9px 4px;border:1px solid #cbd5e1;border-radius:7px;background:white;color:#172033}.palette button.current{outline:2px solid #173b69}.palette button.answered{background:#dff5e8}.palette button.review{background:#fff0c2}.hidden{display:none}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}.timer{font-weight:750;font-size:22px;font-variant-numeric:tabular-nums}.error{color:#b42318}@media(max-width:760px){.grid{grid-template-columns:1fr}.exam{align-items:flex-start;flex-direction:column}}
</style>
</head>
<body class="tg-app"><main class="shell">
<header class="panel"><div><strong>Tagore Vedant Academy · JEE / NEET Computer Based Test</strong><p class="muted">Your answers are saved as you work. You can resume an active attempt on this device or another signed-in device.</p></div><a href="{{ route('tagore.dashboard') }}">← Dashboard</a></header>
<div id="notice" class="panel hidden" role="status"></div>
<section id="examList" class="panel"><h2>Available examinations</h2><div id="exams" class="muted">Loading examinations…</div></section>
<section id="workspace" class="hidden">
<div class="panel exam"><div><strong id="examTitle"></strong><div class="muted" id="examTrack"></div></div><div><div class="muted">Time remaining</div><div class="timer" id="timer">--:--</div></div></div>
<div class="grid"><section class="panel"><div class="muted" id="questionMeta"></div><h2 id="questionTitle">Question</h2><div id="questionStem" class="question"></div><div id="answerArea"></div>
<div class="actions"><button class="btn secondary" id="previous">Previous</button><button class="btn secondary" id="review">Mark for review</button><button class="btn" id="next">Save & next</button><button class="btn" id="submit">Submit exam</button></div></section>
<aside class="panel"><strong>Question palette</strong><p class="muted">Green: answered · Yellow: marked for review</p><div id="palette" class="palette"></div><hr><div class="muted" id="progress"></div></aside></div>
</section>
<section id="result" class="panel hidden"><h2>Examination submitted</h2><div id="resultBody"></div><button class="btn" onclick="location.reload()">Back to examinations</button></section>
</main>
<script>
(() => {
 const base='/tagore/cbt', csrf=document.querySelector('meta[name="csrf-token"]').content;
 const $=id=>document.getElementById(id);
 let attempt=null, questions=[], responses={}, index=0, deadline=0, timerHandle=null, saveQueue=Promise.resolve(), dirtyVersions={}, submitted=false;
 const api=async(url,method='GET',body=null)=>{const r=await fetch(url,{method,headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf},credentials:'same-origin',body:body?JSON.stringify(body):undefined});const d=await r.json().catch(()=>({message:'Unexpected server response'}));if(!r.ok)throw new Error(d.message||'Request failed');return d;};
 const notice=(msg,error=false)=>{$('notice').textContent=msg;$('notice').classList.remove('hidden');$('notice').classList.toggle('error',error);};
 const hideNotice=()=>$('notice').classList.add('hidden');
 const loadExams=async()=>{try{const d=await api(base+'/exams/available');$('exams').replaceChildren();if(!d.exams.length){$('exams').textContent='No examinations are currently open.';return;}d.exams.forEach(exam=>{const card=document.createElement('div');card.className='panel';const title=document.createElement('strong');title.textContent=exam.title;const meta=document.createElement('p');meta.className='muted';meta.textContent=exam.exam_track+' · '+exam.duration_minutes+' minutes';const btn=document.createElement('button');btn.className='btn';btn.textContent='Start / Resume';btn.onclick=()=>start(exam.id);card.append(title,meta,btn);$('exams').append(card);});}catch(e){notice(e.message,true);}};
 const start=async(id)=>{hideNotice();try{const d=await api(base+'/exams/'+id+'/start','POST',{});attempt=d.attempt_id;await openAttempt();}catch(e){notice(e.message,true);}};
 const openAttempt=async()=>{const d=await api(base+'/attempts/'+attempt);questions=d.questions||[];responses=d.responses||{};index=0;deadline=new Date(d.attempt.expires_at).getTime();$('examTitle').textContent=d.exam.title;$('examTrack').textContent=d.exam.exam_track+' · Attempt '+d.attempt.attempt_no;$('examList').classList.add('hidden');$('workspace').classList.remove('hidden');render();tick();if(timerHandle)clearInterval(timerHandle);timerHandle=setInterval(tick,1000);};
 const current=()=>questions[index], currentResponse=()=>responses[String(current().exam_question_id)]||null;
 const markDirty=key=>{dirtyVersions[key]=(dirtyVersions[key]||0)+1;};
 const persistResponse=async(key)=>{const q=questions.find(item=>String(item.exam_question_id)===key);if(!q)return;const version=dirtyVersions[key]||0,r=responses[key]||{};const request=saveQueue.catch(()=>{}).then(()=>api(base+'/attempts/'+attempt+'/response','PUT',{exam_question_id:q.exam_question_id,answer:r.answer??null,marked_for_review:!!r.marked_for_review,time_spent_seconds:r.time_spent_seconds||0}));saveQueue=request;try{await request;if((dirtyVersions[key]||0)===version)delete dirtyVersions[key];}catch(e){notice('Autosave failed: '+e.message,true);throw e;}};
 const save=async()=>{if(!attempt||submitted)return;await persistResponse(String(current().exam_question_id));};
 const flushDirty=async()=>{await saveQueue.catch(()=>{});while(Object.keys(dirtyVersions).length){for(const key of Object.keys(dirtyVersions))await persistResponse(key);}};
 const render=()=>{if(!questions.length){notice('This exam has no questions. Contact your coordinator.',true);return;}const q=current(),r=currentResponse()||{};$('questionMeta').textContent='Question '+(index+1)+' of '+questions.length+' · '+q.subject_code+' · '+q.question_type;$('questionTitle').textContent='Question '+(index+1);$('questionStem').textContent=q.stem;$('answerArea').replaceChildren();const answer=r.answer;
 if(q.question_type==='single_choice'||q.question_type==='multiple_choice'){Object.entries(q.options||{}).forEach(([key,label])=>{const row=document.createElement('label');row.className='choice';const input=document.createElement('input');input.type=q.question_type==='single_choice'?'radio':'checkbox';input.name='answer';input.value=key;input.checked=q.question_type==='single_choice'?answer===key:Array.isArray(answer)&&answer.includes(key);input.onchange=()=>{const old=responses[String(q.exam_question_id)]||{};let next;if(q.question_type==='single_choice')next=key;else{const set=new Set(Array.isArray(old.answer)?old.answer:[]);input.checked?set.add(key):set.delete(key);next=[...set];}responses[String(q.exam_question_id)]={...old,answer:next};markDirty(String(q.exam_question_id));save().catch(()=>{});renderPalette();};const text=document.createElement('span');text.textContent=key+'. '+label;row.append(input,text);$('answerArea').append(row);});}
 else {const input=document.createElement('input');input.type='number';input.step='any';input.placeholder='Enter numerical answer';input.value=answer??'';input.onchange=()=>{responses[String(q.exam_question_id)]={...(responses[String(q.exam_question_id)]||{}),answer:input.value};markDirty(String(q.exam_question_id));save().catch(()=>{});renderPalette();};$('answerArea').append(input);}
 $('review').textContent=r.marked_for_review?'Unmark review':'Mark for review';$('previous').disabled=index===0;$('next').textContent=index===questions.length-1?'Save':'Save & next';renderPalette();};
 const renderPalette=()=>{$('palette').replaceChildren();let answered=0;questions.forEach((q,i)=>{const r=responses[String(q.exam_question_id)]||{},has=!(r.answer===null||r.answer===undefined||r.answer===''||(Array.isArray(r.answer)&&!r.answer.length));if(has)answered++;const b=document.createElement('button');b.textContent=String(i+1);if(i===index)b.classList.add('current');if(has)b.classList.add('answered');if(r.marked_for_review)b.classList.add('review');b.onclick=()=>{index=i;render();};$('palette').append(b);});$('progress').textContent=answered+' of '+questions.length+' answered';};
 const tick=()=>{const left=Math.max(0,Math.floor((deadline-Date.now())/1000));$('timer').textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0');if(left===0&&!submitted){clearInterval(timerHandle);submitExam(true);}};
 const submitExam=async(auto=false)=>{if(submitted)return;if(!auto&&!confirm('Submit your examination now?'))return;try{await flushDirty();const d=await api(base+'/attempts/'+attempt+'/submit','POST',{});submitted=true;clearInterval(timerHandle);$('workspace').classList.add('hidden');$('result').classList.remove('hidden');const r=d.result||{};$('resultBody').textContent='Score: '+r.score+' / '+r.max_score+' · Accuracy: '+r.accuracy+'% · Rank: '+(r.rank||'—')+' / '+(r.candidates||'—')+' · Percentile: '+(r.percentile||0)+'%';}catch(e){notice((auto?'Time expired. ':'')+e.message,true);}};
 $('previous').onclick=()=>{if(index>0){index--;render();}};$('next').onclick=async()=>{await save();if(index<questions.length-1){index++;render();}};$('review').onclick=()=>{const q=current(),key=String(q.exam_question_id),r=responses[key]||{};responses[key]={...r,marked_for_review:!r.marked_for_review};markDirty(key);save().catch(()=>{});render();};$('submit').onclick=()=>submitExam(false);
 loadExams();
})();
</script></body></html>
